        int bracketsTop = opening.getParent().getY();
        int bracketsBottom = opening.getParent().getY() + opening.getParent().getHeight();
        boolean openingLeftOfContent = (opening.getX() + opening.getWidth() <= content.getX()) && (opening.getY() >= contentTop) && (opening.getY() < contentBottom);
        boolean closingRightOfContent = (closing.getX() >= content.getX() + content.getWidth()) && (closing.getY() >= contentTop) && (closing.getY() < contentBottom);
        boolean bracketsSpanContent = (bracketsTop == contentTop) && (bracketsBottom == contentBottom);
